Clase Estadistica
    Privado Definir suma Como Entero;
    Privado Definir cantidad Como Entero;

    Metodo Constructor(unaSuma Como Entero, unaCantidad Como Entero)
        Este.suma <- unaSuma;
        Este.cantidad <- unaCantidad;
    FinMetodo

    Publico Metodo Promedio() Como Real
        Retornar Este.suma / Este.cantidad;
    FinMetodo
FinClase

Proceso CalcularPromedio
    Dimension numeros[5] Como Entero;
    Definir i Como Entero;
    Definir suma Como Entero;
    Definir estadistica Como Estadistica;
    Para i <- 0 Hasta 4 Con Paso 1 Hacer
        Leer numeros[i];
    FinPara
    suma <- 0;
    Para i <- 0 Hasta 4 Con Paso 1 Hacer
        suma <- suma + numeros[i];
    FinPara
    estadistica <- Nuevo Estadistica(suma, 5);
    Escribir estadistica.Promedio();
FinProceso
